<?php
namespace App\Filament\Resources;
use App\Filament\Resources\UpbringingEventResource\Pages;use App\Models\UpbringingEvent;use Illuminate\Support\Facades\DB;
use Filament\Forms;use Filament\Resources\Form;use Filament\Resources\Resource;use Filament\Resources\Table;use Filament\Tables;
class UpbringingEventResource extends Resource{protected static ?string $model=UpbringingEvent::class;protected static bool $shouldRegisterNavigation=false;protected static ?string $modelLabel='мероприятие';protected static ?string $pluralModelLabel='Мероприятия';public static function form(Form $form):Form{return $form->schema([Forms\Components\TextInput::make('title')->label('Мероприятие')->required(),Forms\Components\TextInput::make('direction')->label('Направление')->required(),Forms\Components\Select::make('study_group_id')->label('Группа')->options(fn()=>DB::table('study_groups')->where('active',1)->orderBy('name')->pluck('name','id'))->searchable(),Forms\Components\DateTimePicker::make('starts_at')->label('Начало')->required(),Forms\Components\DateTimePicker::make('ends_at')->label('Окончание'),Forms\Components\TextInput::make('place')->label('Место')])->columns(2);}public static function table(Table $table):Table{return $table->columns([Tables\Columns\TextColumn::make('starts_at')->label('Дата')->dateTime('d.m.Y H:i')->sortable(),Tables\Columns\TextColumn::make('title')->label('Мероприятие')->searchable(),Tables\Columns\TextColumn::make('direction')->label('Направление'),Tables\Columns\TextColumn::make('study_group_id')->label('Группа')->formatStateUsing(fn($state)=>DB::table('study_groups')->where('id',$state)->value('name') ?: '—'),Tables\Columns\BadgeColumn::make('status')->label('Статус')])->actions([Tables\Actions\EditAction::make()->label('Изменить'),Tables\Actions\Action::make('archive')->label('В архив')->color('danger')->requiresConfirmation()->action(fn($record)=>$record->update(['archived_at'=>now()]))]);}public static function getEloquentQuery():\Illuminate\Database\Eloquent\Builder{return parent::getEloquentQuery()->whereNull('archived_at');}public static function getPages():array{return['index'=>Pages\ListUpbringingEvents::route('/'),'create'=>Pages\CreateUpbringingEvent::route('/create'),'edit'=>Pages\EditUpbringingEvent::route('/{record}/edit')];}}
